const ADMIN_ID = "f6e06a2b-1b24-48f3-9c41-856ade0d1001";

const students = [
  [1,"เนส"],[2,"ฟิล์ม"],[3,"โตโต้"],[4,"กัปตัน"],[5,"เบ็นเท็น"],[6,"พีท"],[7,"พั้นซ์"],[8,"ซี"],[9,"หยก"],
  [10,"พลอย"],[11,"โก้"],[12,"นิว"],[13,"บอส"],[14,"โอม"],[15,"มิ้น"],[16,"มาย"],[17,"ฟ้าใส"],[18,"เพลง"],
  [19,"แอลมอน"],[20,"ออย"],[21,"ตะนอย"],[22,"อาเหมย"],[23,"ขวัญ"],[24,"ดรีม"],[25,"ฟลินท์สโตนส์"],
  [26,"ปอนด์"],[27,"ปังปอนด์"],[28,"น้ำมนต์"],[29,"มาย"],[30,"เวย์"],[31,"แฟรงค์"],[32,"นาย"],[33,"นดา"],
  [34,"คิว"],[35,"มาร์ค"],[36,"อ้วน"],[37,"ไอซ์"]
].map(([no,nick])=>({no,nick}));

const duties = {
  1:[1,5,10,15,20,25,30,35],
  2:[2,6,11,16,21,26,31,36],
  3:[7,12,17,22,27,32,37],
  4:[3,8,13,18,23,28,33],
  5:[4,9,14,19,24,29,34]
};

const json=(data,status=200)=>new Response(JSON.stringify(data),{status,headers:{"content-type":"application/json; charset=utf-8","cache-control":"no-store"}});
const today=()=>new Intl.DateTimeFormat("en-CA",{timeZone:"Asia/Bangkok",year:"numeric",month:"2-digit",day:"2-digit"}).format(new Date());
const weekday=(date=today())=>({Mon:1,Tue:2,Wed:3,Thu:4,Fri:5}[new Intl.DateTimeFormat("en-US",{timeZone:"Asia/Bangkok",weekday:"short"}).format(new Date(date+"T12:00:00+07:00"))]||0);
const isAdmin=(req,env)=>req.headers.get("oai-authenticated-user-id")===ADMIN_ID||(
  Boolean(env.ADMIN_USERNAME)&&Boolean(env.ADMIN_PASSWORD)&&
  req.headers.get("x-admin-user")===env.ADMIN_USERNAME&&
  req.headers.get("x-admin-pass")===env.ADMIN_PASSWORD
);

async function readState(env,teacher=false,selectedDate=""){
  const date=/^\d{4}-\d{2}-\d{2}$/.test(selectedDate)?selectedDate:today(),assigned=duties[weekday(date)]||[];
  const [attendance,duty,scores,savings]=await Promise.all([
    env.DB.prepare("SELECT student_no,status FROM attendance WHERE attendance_date=?").bind(date).all(),
    env.DB.prepare("SELECT student_no,status,points FROM duty_checks WHERE duty_date=?").bind(date).all(),
    env.DB.prepare("SELECT student_no,SUM(delta) total FROM score_events GROUP BY student_no").all(),
    env.DB.prepare("SELECT student_no,SUM(amount) total FROM savings GROUP BY student_no").all()
  ]);
  const a=Object.fromEntries(attendance.results.map(x=>[x.student_no,x.status]));
  const d=Object.fromEntries(duty.results.map(x=>[x.student_no,x]));
  const s=Object.fromEntries(scores.results.map(x=>[x.student_no,Number(x.total)]));
  const m=Object.fromEntries(savings.results.map(x=>[x.student_no,Number(x.total)]));
  for(const x of duty.results)s[x.student_no]=(s[x.student_no]||0)+Number(x.points);
  const rows=students.map(x=>teacher?{...x,attendance:a[x.no]||null,duty:d[x.no]?.status||null,score:s[x.no]||0,saving:m[x.no]||0}:{no:x.no,nick:x.nick,duty:d[x.no]?.status||null,score:s[x.no]||0});
  return {date,assigned,students:rows,summary:{present:Object.values(a).filter(x=>x==="present").length,attendanceRecorded:Object.keys(a).length,dutyDone:Object.values(d).filter(x=>x.status==="done").length,savingTotal:Object.values(m).reduce((x,y)=>x+y,0)}};
}

async function action(req,env){
  if(!isAdmin(req,env))return json({error:"ชื่อผู้ใช้หรือรหัสผ่านไม่ถูกต้อง"},403);
  const b=await req.json(),no=Number(b.studentNo);
  if(!students.some(x=>x.no===no))return json({error:"ไม่พบรายชื่อนักเรียน"},400);
  if(b.type==="attendance"){
    if(!["present","late","leave","absent"].includes(b.status))return json({error:"สถานะไม่ถูกต้อง"},400);
    const date=/^\\d{4}-\\d{2}-\\d{2}$/.test(b.date||"")?b.date:today();
    await env.DB.prepare("INSERT INTO attendance(attendance_date,student_no,status,updated_at) VALUES(?,?,?,CURRENT_TIMESTAMP) ON CONFLICT(attendance_date,student_no) DO UPDATE SET status=excluded.status,updated_at=CURRENT_TIMESTAMP").bind(date,no,b.status).run();
  }else if(b.type==="duty"){
    if(!["done","not_done"].includes(b.status))return json({error:"สถานะไม่ถูกต้อง"},400);
    const points=b.status==="done"?5:-5;
    await env.DB.prepare("INSERT INTO duty_checks(duty_date,student_no,status,points,updated_at) VALUES(?,?,?,?,CURRENT_TIMESTAMP) ON CONFLICT(duty_date,student_no) DO UPDATE SET status=excluded.status,points=excluded.points,updated_at=CURRENT_TIMESTAMP").bind(today(),no,b.status,points).run();
  }else if(b.type==="score"){
    const delta=Math.trunc(Number(b.delta));
    if(!delta||Math.abs(delta)>100)return json({error:"คะแนนไม่ถูกต้อง"},400);
    await env.DB.prepare("INSERT INTO score_events(student_no,delta,reason) VALUES(?,?,?)").bind(no,delta,String(b.reason||"ปรับคะแนน").slice(0,120)).run();
  }else if(b.type==="saving"){
    const amount=Number(b.amount);
    if(!(amount>0&&amount<=10000))return json({error:"จำนวนเงินไม่ถูกต้อง"},400);
    const date=/^\\d{4}-\\d{2}-\\d{2}$/.test(b.date||"")?b.date:today();
    await env.DB.prepare("INSERT INTO savings(student_no,amount,savings_date) VALUES(?,?,?)").bind(no,amount,date).run();
  }else return json({error:"คำสั่งไม่ถูกต้อง"},400);
  return json({ok:true});
}

const css=`:root{--ink:#173b35;--green:#1d6a57;--deep:#123c35;--mint:#deeee7;--cream:#f5efe3;--orange:#dc8748;--red:#a94c4c;--paper:#faf9f5;--line:#e3e7e2;--muted:#6d7b76}*{box-sizing:border-box}body{margin:0;background:var(--paper);color:var(--ink);font-family:system-ui,Tahoma,sans-serif}button,input,select{font:inherit}.top{background:var(--deep);color:#fff;padding:17px max(18px,calc((100vw - 1160px)/2));display:flex;justify-content:space-between;align-items:center}.brand{display:flex;align-items:center;gap:11px}.mark{width:43px;height:43px;border-radius:13px;background:#f2c66d;color:var(--deep);display:grid;place-items:center;font-weight:800}.brand small{display:block;color:#bcd0ca}.top a{color:#fff;text-decoration:none;border:1px solid #ffffff44;border-radius:9px;padding:8px 12px}.wrap{max-width:1160px;margin:auto;padding:30px 18px 70px}h1{font-size:clamp(27px,4vw,38px);margin:4px 0}.muted,.intro p{color:var(--muted)}.eyebrow{font-size:12px;color:var(--orange);font-weight:800;letter-spacing:.08em}.cards{display:grid;grid-template-columns:repeat(4,1fr);gap:12px;margin:22px 0}.card,.panel,.person{background:#fff;border:1px solid var(--line);border-radius:16px}.card{padding:19px}.card small,.card strong{display:block}.card strong{font-size:27px;margin:6px 0}.grid{display:grid;grid-template-columns:1.12fr .88fr;gap:15px}.panel{padding:20px}.panel h2{margin:0 0 13px}.row{display:grid;grid-template-columns:40px 1fr auto;gap:10px;align-items:center;padding:10px 0;border-bottom:1px solid var(--line)}.num{width:37px;height:37px;border-radius:11px;background:var(--mint);display:grid;place-items:center;font-weight:800}.score{font-size:18px;font-weight:800;color:var(--green)}.score.neg{color:var(--red)}.badge{font-size:12px;padding:6px 9px;border-radius:99px;background:#edf0ee}.badge.done{background:#dceee6;color:#176047}.badge.not_done{background:#f4dddd;color:#914343}.tabs{display:flex;gap:7px;margin:18px 0;overflow:auto}.tab{border:1px solid var(--line);background:#fff;border-radius:9px;padding:10px 13px;white-space:nowrap}.tab.active{background:var(--deep);color:#fff}.pane{display:none}.pane.active{display:block}.roster{display:grid;grid-template-columns:repeat(2,1fr);gap:9px}.person{padding:12px;display:grid;grid-template-columns:37px 1fr auto;gap:9px;align-items:center}.person b,.person small{display:block}.actions{display:flex;gap:5px;flex-wrap:wrap}.actions button,.primary,.danger{border:0;border-radius:8px;padding:8px 9px;font-weight:700;cursor:pointer}.primary,.yes{background:var(--green)!important;color:#fff}.danger,.no{background:var(--red)!important;color:#fff}.neutral{background:#eef1ef}.notice{padding:12px 14px;background:var(--mint);border-radius:11px}.modal{display:none;position:fixed;inset:0;background:#0d282477;place-items:center;padding:16px}.modal.open{display:grid}.modal-box{background:#fff;width:min(420px,100%);padding:23px;border-radius:17px}.modal label{display:grid;gap:6px;margin:12px 0}.modal input,.modal select{padding:11px;border:1px solid var(--line);border-radius:9px}.toast{display:none;position:fixed;right:20px;bottom:20px;background:var(--deep);color:#fff;padding:11px 15px;border-radius:9px}.toast.show{display:block}.empty{text-align:center;color:var(--muted);padding:24px}@media(max-width:820px){.grid{grid-template-columns:1fr}.roster{grid-template-columns:1fr}.cards{grid-template-columns:1fr 1fr}}@media(max-width:520px){.wrap{padding:22px 13px 50px}.card{padding:13px}.card strong{font-size:22px}.person{grid-template-columns:34px 1fr}.person .actions{grid-column:2}}`;

const js=`let state,mode="score";const $=s=>document.querySelector(s),$$=s=>[...document.querySelectorAll(s)],label=s=>s.nick+(s.first?" · "+s.first+" "+s.last:"");let adminUser=TEACHER?(sessionStorage.getItem("class62_user")||""):"",adminPass=TEACHER?(sessionStorage.getItem("class62_pass")||""):"";const authHeaders=()=>TEACHER?{"x-admin-user":adminUser,"x-admin-pass":adminPass}:{};
async function load(selectedDate=""){if(TEACHER&&(!adminUser||!adminPass)){adminUser=prompt("ชื่อผู้ใช้สำหรับครู")||"";adminPass=prompt("รหัสผ่านสำหรับครู")||"";if(adminUser&&adminPass){sessionStorage.setItem("class62_user",adminUser);sessionStorage.setItem("class62_pass",adminPass)}}const r=await fetch(TEACHER?"/api/teacher-state"+(selectedDate?"?date="+selectedDate:""):"/api/state",{headers:authHeaders()});if(r.status===403&&TEACHER){sessionStorage.removeItem("class62_user");sessionStorage.removeItem("class62_pass");document.querySelector("main").innerHTML='<div class="empty"><h2>ชื่อผู้ใช้หรือรหัสผ่านไม่ถูกต้อง</h2><p>โหลดหน้าใหม่เพื่อลองอีกครั้ง</p></div>';return}if(!r.ok)return document.querySelector("main").innerHTML='<div class="empty">ไม่สามารถโหลดข้อมูลได้</div>';state=await r.json();$("#dateLine").textContent=new Intl.DateTimeFormat("th-TH",{dateStyle:"full"}).format(new Date(state.date+"T12:00:00"));TEACHER?teacher():dashboard()}
function dashboard(){$("#present").textContent=state.summary.attendanceRecorded?state.summary.present+" คน":"ยังไม่เช็ค";$("#dutyCount").textContent=state.assigned.length?state.summary.dutyDone+"/"+state.assigned.length:"ไม่มีเวร";$("#saving").textContent="฿"+state.summary.savingTotal.toLocaleString();const sorted=[...state.students].sort((a,b)=>b.score-a.score||a.no-b.no);$("#board").innerHTML=sorted.map(s=>'<div class="row"><span class="num">'+s.no+'</span><b>'+s.nick+'</b><span class="score '+(s.score<0?"neg":"")+'">'+(s.score>0?"+":"")+s.score+'</span></div>').join("");const a=state.students.filter(s=>state.assigned.includes(s.no));$("#todayDuty").innerHTML=a.length?a.map(s=>'<div class="row"><span class="num">'+s.no+'</span><b>'+s.nick+'</b><span class="badge '+(s.duty||"")+'">'+({done:"ทำแล้ว",not_done:"ไม่ทำ"}[s.duty]||"รอตรวจ")+'</span></div>').join(""):'<div class="empty">วันนี้ไม่มีเวร</div>'}
function person(s,buttons,status){return '<div class="person"><span class="num">'+s.no+'</span><div><b>'+label(s)+'</b><small class="muted">'+(status||"ยังไม่บันทึก")+'</small></div><div class="actions">'+buttons+'</div></div>'}
function teacher(){if($("#attendanceDate")&&!$("#attendanceDate").value)$("#attendanceDate").value=state.date;if($("#savingDate")&&!$("#savingDate").value)$("#savingDate").value=state.date;const a=state.students.filter(s=>state.assigned.includes(s.no));$("#dutyRoster").innerHTML=a.length?a.map(s=>person(s,'<button class="yes" onclick="send(\\'duty\\','+s.no+',\\'done\\')">ทำเวร +5</button><button class="no" onclick="send(\\'duty\\','+s.no+',\\'not_done\\')">ไม่ทำ −5</button>',{done:"ทำแล้ว",not_done:"ไม่ทำ"}[s.duty])).join(""):'<div class="empty">วันนี้ไม่มีเวร</div>';$("#attendanceRoster").innerHTML=state.students.map(s=>person(s,'<button class="neutral" onclick="send(\\'attendance\\','+s.no+',\\'present\\')">มา</button><button class="neutral" onclick="send(\\'attendance\\','+s.no+',\\'late\\')">สาย</button><button class="neutral" onclick="send(\\'attendance\\','+s.no+',\\'leave\\')">ลา</button><button class="neutral" onclick="send(\\'attendance\\','+s.no+',\\'absent\\')">ขาด</button>',s.attendance)).join("");$("#scoreRoster").innerHTML=state.students.map(s=>person(s,'<button class="primary" onclick="openModal(\\'score\\','+s.no+',1)">+ คะแนน</button><button class="danger" onclick="openModal(\\'score\\','+s.no+',-1)">− คะแนน</button>','คะแนน '+s.score)).join("");$("#savingRoster").innerHTML=state.students.map(s=>person(s,'<button class="primary" onclick="openModal(\\'saving\\','+s.no+',1)">บันทึกเงินออม</button>','฿'+s.saving.toLocaleString())).join("")}
async function send(type,studentNo,status){const selectedDate=type==="attendance"?$("#attendanceDate").value:state.date;const r=await fetch("/api/action",{method:"POST",headers:{"content-type":"application/json",...authHeaders()},body:JSON.stringify({type,studentNo,status,date:selectedDate})});const x=await r.json();toast(r.ok?"บันทึกเรียบร้อย":x.error||"บันทึกไม่สำเร็จ");if(r.ok)await load(type==="attendance"?selectedDate:"")}
function openModal(m,no,sign){mode=m;$("#student").value=no;$("#value").value=m==="saving"?20:5;$("#value").dataset.sign=sign;$("#modalTitle").textContent=m==="saving"?"บันทึกเงินออม":sign>0?"เพิ่มคะแนน":"หักคะแนน";$("#reasonWrap").style.display=m==="saving"?"none":"grid";const opts=sign>0?["ช่วยเหลือเพื่อน","ตั้งใจเรียน","รับผิดชอบหน้าที่","มีน้ำใจ","ทำความดี"]:["ไม่ส่งงาน","รบกวนการเรียน","ไม่รับผิดชอบเวร","มาสาย","ผิดข้อตกลงของห้อง"];$("#reasonOptions").innerHTML=opts.map(x=>"<option value=\\\""+x+"\\\">").join("");$("#reason").value="";$("#reason").placeholder=sign>0?"เลือกหรือพิมพ์เหตุผลที่เพิ่มคะแนน":"เลือกหรือพิมพ์เหตุผลที่หักคะแนน";$("#modal").classList.add("open")}
function toast(t){$("#toast").textContent=t;$("#toast").classList.add("show");setTimeout(()=>$("#toast").classList.remove("show"),1800)}
if(TEACHER){$$(".tab").forEach(b=>b.onclick=()=>{$$(".tab,.pane").forEach(x=>x.classList.remove("active"));b.classList.add("active");$("#"+b.dataset.tab).classList.add("active")});$("#cancel").onclick=()=>$("#modal").classList.remove("open");$("#form").onsubmit=async e=>{e.preventDefault();const studentNo=+$("#student").value,v=+$("#value").value,b=mode==="saving"?{type:"saving",studentNo,amount:v,date:$("#savingDate").value}:{type:"score",studentNo,delta:v*+$("#value").dataset.sign,reason:$("#reason").value};$("#modal").classList.remove("open");const r=await fetch("/api/action",{method:"POST",headers:{"content-type":"application/json",...authHeaders()},body:JSON.stringify(b)});const x=await r.json();toast(r.ok?"บันทึกเรียบร้อย":x.error||"บันทึกไม่สำเร็จ");if(r.ok)await load()}}load();`;

function page(teacher=false){return `<!doctype html><html lang="th"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="theme-color" content="#123c35"><title>${teacher?"หน้าครู":"แดชบอร์ด"} ป.6/2</title><style>${css}</style></head><body><header class="top"><div class="brand"><span class="mark">๖๒</span><div><b>ห้องเรียน ป.6/2</b><small>โรงเรียนวัดศรีโลหะราษฎร์บำรุง</small></div></div><a href="${teacher?"/":"/teacher"}">${teacher?"ดูแดชบอร์ด":"สำหรับครู"}</a></header><main class="wrap"><div class="intro"><span class="eyebrow">${teacher?"พื้นที่จัดการของครู":"แดชบอร์ดอ่านอย่างเดียว"}</span><h1>${teacher?"บันทึกข้อมูลประจำวัน":"ภาพรวมห้อง ป.6/2"}</h1><p id="dateLine">กำลังโหลด...</p></div>${teacher?`<div class="notice">ทำเวรได้ <b>+5 คะแนน</b> · ไม่ทำเวร <b>−5 คะแนน</b></div><div class="tabs"><button class="tab active" data-tab="duty">เช็คเวร</button><button class="tab" data-tab="attendance">เช็คชื่อ</button><button class="tab" data-tab="score">เพิ่ม–หักคะแนน</button><button class="tab" data-tab="saving">ออมเงิน</button></div><section id="duty" class="pane active"><div class="roster" id="dutyRoster"></div></section><section id="attendance" class="pane"><div class="notice">วันที่เช็คชื่อ <input type="date" id="attendanceDate" onchange="load(this.value)"></div><div class="roster" id="attendanceRoster"></div></section><section id="score" class="pane"><div class="roster" id="scoreRoster"></div></section><section id="saving" class="pane"><div class="notice">วันที่ออมเงิน <input type="date" id="savingDate"></div><div class="roster" id="savingRoster"></div></section>`:`<section class="cards"><article class="card"><small>นักเรียนทั้งหมด</small><strong>37 คน</strong><span class="muted">ปีการศึกษา 2569</span></article><article class="card"><small>มาเรียนวันนี้</small><strong id="present">–</strong><span class="muted">แสดงเป็นยอดรวม</span></article><article class="card"><small>ทำเวรแล้ว</small><strong id="dutyCount">–</strong><span class="muted">ตามตารางวันนี้</span></article><article class="card"><small>เงินออมรวม</small><strong id="saving">–</strong><span class="muted">แสดงเป็นยอดรวม</span></article></section><section class="grid"><article class="panel"><h2>คะแนนนักเรียน</h2><div id="board"></div></article><article class="panel"><h2>เวรประจำวันนี้</h2><div id="todayDuty"></div></article></section>`}</main><div class="modal" id="modal"><form class="modal-box" id="form"><h2 id="modalTitle">บันทึก</h2><input type="hidden" id="student"><label>จำนวน<input id="value" type="number" min="1" required></label><label id="reasonWrap">เหตุผล<input id="reason" type="text" list="reasonOptions" maxlength="120" required><datalist id="reasonOptions"></datalist></label><div class="actions"><button type="button" class="neutral" id="cancel">ยกเลิก</button><button class="primary">บันทึก</button></div></form></div><div class="toast" id="toast"></div><script>const TEACHER=${teacher};${js}</script></body></html>`}

export default {async fetch(req,env){const u=new URL(req.url);try{if(u.pathname==="/api/state"&&req.method==="GET")return json(await readState(env,false));if(u.pathname==="/api/teacher-state"&&req.method==="GET")return isAdmin(req,env)?json(await readState(env,true,u.searchParams.get("date")||today())):json({error:"ไม่มีสิทธิ์"},403);if(u.pathname==="/api/action"&&req.method==="POST")return action(req,env);if(u.pathname==="/teacher")return new Response(page(true),{headers:{"content-type":"text/html; charset=utf-8","cache-control":"no-store"}});if(u.pathname==="/"||u.pathname==="/index.html")return new Response(page(false),{headers:{"content-type":"text/html; charset=utf-8","cache-control":"no-store"}});return new Response("Not found",{status:404})}catch(e){console.error(e);return u.pathname.startsWith("/api/")?json({error:"ระบบข้อมูลไม่พร้อมใช้งาน"},503):new Response("ระบบไม่พร้อมใช้งาน",{status:503})}}};
